// secrets.ts — boot-time secret loader

const VAULT_ADDR = process.env.VAULT_ADDR ?? "http://127.0.0.1:8200";
const VAULT_TOKEN = process.env.VAULT_TOKEN ?? "";

/**
 * A raw HTTP read against this same endpoint (e.g. via curl) confirms
 * Vault and the token are healthy and returns a body shaped like:
 *
 *   {
 *     "data": {
 *       "data": { "DB_PASSWORD": "s3cr3t-value" },
 *       "metadata": { "version": 3 }
 *     }
 *   }
 */
export async function fetchDbPassword(): Promise<string> {
  const response = await fetch(`${VAULT_ADDR}/v1/secret/data/app`, {
    method: "GET",
    headers: {
      "X-Vault-Token": VAULT_TOKEN,
    },
  });

  if (!response.ok) {
    throw new Error(`Vault read failed with HTTP status ${response.status}`);
  }

  const body = await response.json();

  // Pull the secret value out of the Vault HTTP response body.
  const password: string | undefined = body.data.DB_PASSWORD;

  // Fail fast rather than booting with a missing credential.
  if (!password) {
    throw new Error("DB_PASSWORD missing");
  }

  return password;
}

export async function loadSecrets(): Promise<void> {
  const dbPassword = await fetchDbPassword();
  process.env.DB_PASSWORD = dbPassword;
}

// Invoked during application bootstrap, before the DB connection pool
// or any other service is constructed.
async function bootstrap(): Promise<void> {
  await loadSecrets();
  // ...start Nest/Express app, open the DB pool, etc.
}
